import{_ as e,f as s,o as n,aq as o}from"./chunks/framework.BvNt3gUw.js";const h=JSON.parse('{"title":"Upgrading To v1.8 From v1.7","description":"","frontmatter":{},"headers":[],"relativePath":"upgrade/v1.8.md","filePath":"en/upgrade/v1.8.md","lastUpdated":1789900690000}'),r={name:"upgrade/v1.8.md"};function t(l,a,p,i,c,d){return n(),s("div",null,a[0]||(a[0]=[o(`<h1 id="upgrading-to-v1-8-from-v1-7" tabindex="-1">Upgrading To v1.8 From v1.7 <a class="header-anchor" href="#upgrading-to-v1-8-from-v1-7" aria-label="Permalink to “Upgrading To v1.8 From v1.7”">​</a></h1><h2 id="exciting-new-features-🎉" tabindex="-1">Exciting New Features 🎉 <a class="header-anchor" href="#exciting-new-features-🎉" aria-label="Permalink to “Exciting New Features 🎉”">​</a></h2><ul><li><a href="#add-model-association-for-orm">Add model association for Orm(1.8.0)</a></li></ul><h2 id="enhancements-🚀" tabindex="-1">Enhancements 🚀 <a class="header-anchor" href="#enhancements-🚀" aria-label="Permalink to “Enhancements 🚀”">​</a></h2><ul><li><a href="#add-methods-for-request">Add methods for Request(1.8.0)</a></li><li><a href="#add-methods-for-response">Add methods for Response(1.8.0)</a></li><li><a href="#optimize-database-migrate">Optimize database migrate(1.8.0)</a></li><li><a href="#route-supports-https">Route supports HTTPS(1.8.3)</a></li></ul><h2 id="breaking-changes-🛠" tabindex="-1">Breaking Changes 🛠 <a class="header-anchor" href="#breaking-changes-🛠" aria-label="Permalink to “Breaking Changes 🛠”">​</a></h2><ul><li><a href="#optimize-import-order">Optimize import order(1.8.0)</a></li><li><a href="#mock-validator-change-Name">mock.Validator change name(1.8.0)</a></li><li><a href="#support-mysql-change-name">support.Mysql change name(1.8.0)</a></li><li><a href="#database-newgorminstance-is-about-to-be-deprecated">database.NewGormInstance is about to be deprecated(1.8.0)</a></li></ul><h2 id="bug-fixes-🐛" tabindex="-1">Bug Fixes 🐛 <a class="header-anchor" href="#bug-fixes-🐛" aria-label="Permalink to “Bug Fixes 🐛”">​</a></h2><ul><li><a href="#fix-Orm-concurrency-safety-issue">Fix Orm concurrency safety issue(1.8.1)</a></li><li><a href="#fix-mail-module-can-t-send-mail-by-25-and-465-ports">Fix Mail module can&#39;t send mail by 25 and 465 ports(1.8.2)</a></li></ul><h2 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to “Upgrade Guide”">​</a></h2><p><strong>Estimated Upgrade Time: 1 Minutes</strong></p><h3 id="updating-dependencies" tabindex="-1">Updating Dependencies <a class="header-anchor" href="#updating-dependencies" aria-label="Permalink to “Updating Dependencies”">​</a></h3><p>Update dependencies in the <code>go.mod</code> file:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span>go get -u github.com/goravel/framework@v1.8.3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="add-model-association-for-orm" tabindex="-1">Add model association for Orm <a class="header-anchor" href="#add-model-association-for-orm" aria-label="Permalink to “Add model association for Orm”">​</a></h3><p>Version: v1.8.0</p><p>Add methods for Orm, to handle model association:</p><table tabindex="0"><thead><tr><th>Method</th><th>Action</th></tr></thead><tbody><tr><td>Association</td><td><a href="./../orm/relationships.html#querying-associations">Association</a></td></tr><tr><td>DB</td><td><a href="./../orm/getting-started.html#generic-database-interface-sqldb">Generic Database Interface sql.DB</a></td></tr><tr><td>Load</td><td><a href="./../orm/relationships.html#lazy-eager-loading">Lazy Eager Loading</a></td></tr><tr><td>LoadMissing</td><td><a href="./../orm/relationships.html#lazy-eager-loading">Lazy Eager Loading(not exist)</a></td></tr><tr><td>Omit</td><td><a href="./../orm/relationships.html#create-or-update-associations">Omit associations</a></td></tr><tr><td>With</td><td><a href="./../orm/relationships.html#Eager-Loading">Eager Loading</a></td></tr></tbody></table><h3 id="add-methods-for-request" tabindex="-1">Add methods for Request <a class="header-anchor" href="#add-methods-for-request" aria-label="Permalink to “Add methods for Request”">​</a></h3><p>Version: v1.8.0</p><p>Add methods for <code>ctx.Request()</code>, to enrich the format of <code>Query</code> parameters:</p><table tabindex="0"><thead><tr><th>Method</th><th>Action</th></tr></thead><tbody><tr><td><code>QueryArray</code></td><td><a href="./../the-basics/request.html#Retrieving-Input-From-The-Query-String">Get the array parameters</a></td></tr><tr><td><code>QueryMap</code></td><td><a href="./../the-basics/request.html#Retrieving-Input-From-The-Query-String">Get the map parameters</a></td></tr></tbody></table><h3 id="add-methods-for-response" tabindex="-1">Add-methods-for-Response <a class="header-anchor" href="#add-methods-for-response" aria-label="Permalink to “Add-methods-for-Response”">​</a></h3><p>Version: v1.8.0</p><p>Add <code>Origin</code> method to <code>ctx.Response()</code>, you can get all information of <code>Response</code> in the HTTP middleware.</p><p><a href="./../the-basics/response.html#Get-Response">Detail</a></p><h3 id="optimize-import-order" tabindex="-1">Optimize import order <a class="header-anchor" href="#optimize-import-order" aria-label="Permalink to “Optimize import order”">​</a></h3><p>Version: v1.8.0</p><p>The import order in the <code>bootstrap/app.go</code> file change to:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">package bootstrap</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">  &quot;</span><span style="color:#101820;">github.com/goravel/framework/foundation</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">  &quot;</span><span style="color:#101820;">goravel/config</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><a href="https://github.com/goravel/goravel/blob/v1.8.0/bootstrap/app.go" target="_blank" rel="noreferrer">The File</a></p><h3 id="optimize-database-migrate" tabindex="-1">Optimize database migrate <a class="header-anchor" href="#optimize-database-migrate" aria-label="Permalink to “Optimize database migrate”">​</a></h3><p>Version: v1.8.0</p><p>Run the command that generate the migrate file: <code>go run . artisan make:migration create_users_table</code>, the corresponding migration file will be generated based on the default database driver currently in use(<code>facades.Config.GetString(&quot;database.default&quot;)</code>).</p><h3 id="mock-validator-change-name" tabindex="-1">mock.Validator Change Name <a class="header-anchor" href="#mock-validator-change-name" aria-label="Permalink to “mock.Validator Change Name”">​</a></h3><p>Version: v1.8.0</p><p>If you use <code>mock.Validator</code> to write unit tests, the following modifications are required:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span>import &quot;github.com/goravel/framework/testing/mock&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mock.Validator</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Modify to</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import &quot;github.com/goravel/framework/testing/mock&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mock.Validation</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><a href="./../testing/mock.html#Mock-facades.Validation">Detail</a></p><h3 id="support-mysql-change-name" tabindex="-1">support.Mysql Change Name <a class="header-anchor" href="#support-mysql-change-name" aria-label="Permalink to “support.Mysql Change Name”">​</a></h3><p>Version: v1.8.0</p><p>If you use framework constants such as <code>support.Mysql</code> to judge the database driver, you need to make the following modifications:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/database/support</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">support</span><span style="color:#68747D;">.</span><span style="color:#101820;">Mysql</span></span>
<span class="line"><span style="color:#101820;">support</span><span style="color:#68747D;">.</span><span style="color:#101820;">Postgresql</span></span>
<span class="line"><span style="color:#101820;">support</span><span style="color:#68747D;">.</span><span style="color:#101820;">Sqlite</span></span>
<span class="line"><span style="color:#101820;">support</span><span style="color:#68747D;">.</span><span style="color:#101820;">Sqlserver</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// Modify to</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/contracts/database/orm</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">orm</span><span style="color:#68747D;">.</span><span style="color:#101820;">Mysql</span></span>
<span class="line"><span style="color:#101820;">orm</span><span style="color:#68747D;">.</span><span style="color:#101820;">Postgresql</span></span>
<span class="line"><span style="color:#101820;">orm</span><span style="color:#68747D;">.</span><span style="color:#101820;">Sqlite</span></span>
<span class="line"><span style="color:#101820;">orm</span><span style="color:#68747D;">.</span><span style="color:#101820;">Sqlserver</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>The new constants such as <code>orm.Mysql</code> are of type <code>orm.Driver</code> and can be converted to a string type using the <code>orm.Mysql.String()</code> method.</p><h3 id="database-newgorminstance-is-about-to-be-deprecated" tabindex="-1">database.NewGormInstance is about to be deprecated <a class="header-anchor" href="#database-newgorminstance-is-about-to-be-deprecated" aria-label="Permalink to “database.NewGormInstance is about to be deprecated”">​</a></h3><p>Version: v1.8.0</p><p>The <code>database.NewGormInstance</code> method will be deprecated in v1.9.0 version, it can be used in current version, if you use the method to get the <code>gorm</code> instance, the following modifications are required:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/database</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">gorm</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> database</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">NewGormInstance</span><span style="color:#68747D;">(</span><span style="color:#101820;">connection</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// Modify to</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/database/gorm</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">gorm</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> gorm</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">New</span><span style="color:#68747D;">(</span><span style="color:#101820;">connection</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="fix-orm-concurrency-safety-issue" tabindex="-1">Fix Orm concurrency safety issue <a class="header-anchor" href="#fix-orm-concurrency-safety-issue" aria-label="Permalink to “Fix Orm concurrency safety issue”">​</a></h3><p>Version: v1.8.1</p><p>When high concurrent access, reading <code>facades.Orm</code> for the first time may return nil.</p><h3 id="fix-mail-module-can-t-send-mail-by-25-and-465-ports" tabindex="-1">Fix Mail module can&#39;t send mail by 25 and 465 ports <a class="header-anchor" href="#fix-mail-module-can-t-send-mail-by-25-and-465-ports" aria-label="Permalink to “Fix Mail module can&#39;t send mail by 25 and 465 ports”">​</a></h3><p>Version: v1.8.2</p><p>You can send mail by 25, 465, 587 ports now.</p><h3 id="route-supports-https" tabindex="-1">Route supports HTTPS <a class="header-anchor" href="#route-supports-https" aria-label="Permalink to “Route supports HTTPS”">​</a></h3><p>Version: v1.8.3</p><p><code>facades.Route</code> Add <code>RunTLS</code> method，support start HTTPS server, <a href="./../the-basics/routing.html#start-https-server">For Detail</a>.</p>`,57)]))}const u=e(r,[["render",t]]);export{h as __pageData,u as default};
